export const assets={"/about/index.html":["text/html; charset=utf-8",""],"/assets/brand-logo.jpg":["image/jpeg",""],"/assets/favicon-s.png":["image/png",""],"/assets/favicon.svg":["image/svg+xml",""],"/assets/gumroad.js":["text/javascript; charset=utf-8",""],"/assets/javier-traver.jpg":["image/jpeg",""],"/assets/portfolio/gigantes.webp":["image/webp",""],"/assets/portfolio/greens.webp":["image/webp",""],"/assets/portfolio/more.webp":["image/webp",""],"/assets/portfolio/sirtraver.webp":["image/webp",""],"/assets/portfolio/type-in-motion.webp":["image/webp",""],"/assets/portfolio/wobble.webp":["image/webp",""],"/assets/portfolio.json":["application/json; charset=utf-8",""],"/assets/site.css":["text/css; charset=utf-8",""],"/assets/site.js":["text/javascript; charset=utf-8",""],"/es/about/index.html":["text/html; charset=utf-8",""],"/es/index.html":["text/html; charset=utf-8",""],"/es/portfolio/index.html":["text/html; charset=utf-8",""],"/es/resources/index.html":["text/html; charset=utf-8",""],"/favicon.ico":["image/x-icon",""],"/index.html":["text/html; charset=utf-8",""],"/portfolio/index.html":["text/html; charset=utf-8",""],"/resources/index.html":["text/html; charset=utf-8",""],"/robots.txt":["text/plain; charset=utf-8","VXNlci1hZ2VudDogKgpBbGxvdzogLwpEaXNhbGxvdzogL2FwaS8KU2l0ZW1hcDogaHR0cHM6Ly9zaXJ0cmF2ZXIuY29tL3NpdGVtYXAueG1sCg=="],"/sitemap.xml":["application/xml; charset=utf-8",""]};
const API='https://api.gumroad.com/v2/products';
let memo=null;
export function publicProducts(items,demoId='') {
 if(!Array.isArray(items))throw new Error('Invalid catalog');
 return items.filter(p=>p&&!p.deleted&&(p.published===true||p.id===demoId)).flatMap(p=>{
  let url;try{url=new URL(p.short_url);}catch{return []}
  if(url.protocol!=='https:'||url.hostname!=='sirtraver.gumroad.com'||!url.pathname.startsWith('/l/'))return [];
  let image='';try{const u=new URL(p.thumbnail_url);if(u.protocol==='https:'&&['public-files.gumroad.com','gumroad-public-storage.s3.amazonaws.com'].includes(u.hostname))image=u.href}catch{}
  return [{id:p.id,title:String(p.name||'Recurso').slice(0,180),summary:String(p.custom_summary||'').slice(0,260),url:url.href,image,price:p.price===0?'Free · €0':String(p.formatted_price||''),published:p.published===true,demo:p.id===demoId}];
 });
}
export async function catalog(request,env,ctx,fetcher=fetch) {
 if(request.method!=='GET')return new Response(null,{status:405,headers:{Allow:'GET'}});
 const json=(body,status=200,headers={})=>Response.json(body,{status,headers:{'Cache-Control':'no-store',...headers}});
 if(!env.GUMROAD_ACCESS_TOKEN)return json({status:'unavailable',products:[]},503);
 const identity=env.GUMROAD_ACCESS_TOKEN+'|'+(env.GUMROAD_DEMO_PRODUCT_ID||'');
 if(memo&&memo.identity===identity&&memo.expires>Date.now())return json({status:'ok',products:memo.products},200,{'Cache-Control':'public, max-age=30'});
 try{
  const response=await fetcher(API,{headers:{Authorization:'Bearer '+env.GUMROAD_ACCESS_TOKEN,Accept:'application/json'},signal:AbortSignal.timeout(10000)});
  if(!response.ok)throw new Error('upstream');const data=await response.json();if(data.success!==true)throw new Error('upstream');
  const products=publicProducts(data.products,env.GUMROAD_DEMO_PRODUCT_ID||'');
  const out=json({status:'ok',products},200,{'Cache-Control':'public, max-age=30, s-maxage=60'});
  memo={identity,products,expires:Date.now()+60000};return out;
 }catch{return json({status:'unavailable',products:[]},503)}
}
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderResources(products,language='en'){
 const es=language==='es';
 if(!products.length)return '<p class="catalog-status">'+(es?'Todavía no hay productos disponibles.':'No products available yet.')+'</p>';
 return products.map(p=>'<article class="project-card product-card">'+(p.image?'<img src="'+escape(p.image)+'" alt="Cover of '+escape(p.title)+'" width="600" height="600" loading="lazy">':'')+'<div class="card-caption"><h2>'+escape(p.title)+'</h2></div><p class="product-summary">'+escape(p.summary)+'</p><div class="product-bottom"><span>'+escape(es?p.price.replace('Free · €0','Gratis · 0 €'):p.price)+'</span>'+(p.published?'<a href="'+escape(p.url)+'" target="_blank" rel="noopener noreferrer">'+(es?'Ver en Gumroad ↗':'View on Gumroad ↗')+'</a>':'<span class="product-state">'+(es?'Demo / En preparación':'Demo / Coming soon')+'</span>')+'</div></article>').join('');
}
export function resourceSchema(products){return JSON.stringify({'@context':'https://schema.org','@type':'ItemList','name':'SIRTRAVER digital resources','itemListElement':products.filter(p=>p.published).map((p,i)=>({'@type':'ListItem','position':i+1,'item':{'@type':'CreativeWork','name':p.title,'url':p.url,'image':p.image,'creator':{'@id':'https://sirtraver.com/#javier-traver'}}}))}).replace(/</g,'\\u003c');}
const redirects={'/portfolio':'/','/portfolio/':'/','/es/portfolio':'/es/','/es/portfolio/':'/es/','/recursos':'/resources/','/recursos/':'/resources/','/recursos/brief-claro':'/resources/','/recursos/brief-claro/':'/resources/','/sobre-mi':'/about/','/sobre-mi/':'/about/'};
export default {
 async fetch(request,env,ctx){
  const u=new URL(request.url);
  if(!['GET','HEAD'].includes(request.method))return new Response(null,{status:405,headers:{Allow:'GET, HEAD'}});
  if(u.hostname==='sirtraver.sirtraver.chatgpt.site'||u.hostname==='www.sirtraver.com'){u.hostname='sirtraver.com';return Response.redirect(u.href,301);}
  if(u.pathname==='/api/catalogo-gumroad'){const r=await catalog(request,env,ctx);r.headers.set('X-Robots-Tag','noindex');return r;}
  let path;try{path=decodeURIComponent(u.pathname)}catch{return new Response('Not found',{status:404,headers:{'X-Robots-Tag':'noindex'}})}
  if(redirects[path])return Response.redirect(new URL(redirects[path],u).href,301);
  if(path.includes('..'))return new Response('Not found',{status:404,headers:{'X-Robots-Tag':'noindex'}});
  if(!path.endsWith('/')&&assets[path+'/index.html'])return Response.redirect(new URL(path+'/',u).href,301);
  if(path.endsWith('/'))path+='index.html';
  const item=assets[path];if(!item)return new Response('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page not found | SIRTRAVER</title><link rel="icon" type="image/png" href="/assets/favicon-s.png?v=10"><link rel="shortcut icon" href="/favicon.ico?v=10"><meta name="robots" content="noindex"><link rel="stylesheet" href="/assets/site.css"></head><body><main class="not-found"><h1>404</h1><p>This page could not be found.</p><a href="/">Back to SIRTRAVER</a></main></body></html>',{status:404,headers:{'Content-Type':'text/html; charset=utf-8','X-Robots-Tag':'noindex'}});
  const [type,b64]=item;const bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));let body=bytes;
  if(path==='/resources/index.html'||path==='/es/resources/index.html'){
   const language=path.startsWith('/es/')?'es':'en';
   const response=await catalog(new Request(request.url,{method:'GET'}),env,ctx);const data=await response.json();
   const html=new TextDecoder().decode(bytes);const content=data.status==='ok'?renderResources(data.products,language):'<p class="catalog-status">The catalog is temporarily unavailable. Please try again shortly.</p>';
   body=html.replace(/<!--resources-->.*?<!--\/resources-->/s,content);
   if(data.status==='ok')body=body.replace('</head>','<script type="application/ld+json">'+resourceSchema(data.products)+'</script></head>');
  }
  return new Response(request.method==='HEAD'?null:body,{headers:{'Content-Type':type,'Cache-Control':type.startsWith('text/html')?'no-cache':'public, max-age=300','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin'}});
 }
};
